/// <summary>
/// Extension of WHSWarehouseRelease for special WHS release for weighing process
/// </summary>
public class AVARUMWHSWarehouseRelease_SalesLine extends WHSWarehouseRelease
{
}

Method.Source:
/// <summary>
/// WHS Release for a salesline
/// </summary>
/// <param name = "_salesLine">salesline</param>
/// <param name = "_creditMaxCheck">Do credit check</param>
static public void salesReleaseLine_AVA(SalesLine _salesLine, CustCreditMaxCheck _creditMaxCheck=TypeOfCreditmaxCheck::None)
{
    //@ananlogous to WHSWarehouseRelease::salesFormRelease(salesTable, creditMaxCheck) - but only for one line
    WHSReleaseToWarehouseId releaseToWarehouseId = WHSTmpReleaseToWarehouse::getNextReleaseToWarehouseId();
    WHSTmpReleaseToWarehouse        releaseToWarehouse;
    SalesTable locSalesTable=_salesLine.salesTable();

    if (!locSalesTable.canReleaseToWarehouse())
    {
        throw error(strFmt("@WAX2951", locSalesTable.SalesId));
    }

    WHSWarehouseRelease::checkSalesOrderDeliveryAddress(locSalesTable);
    AVARUMWHSWarehouseRelease_SalesLine::checkSalesOrderDeliveryName_AVA(locSalesTable);

    //WHSWarehouseRelease::interCompanyUpdateSalesPrice(_salesTable);
    WHSWarehouseRelease::creditLimitCheck(locSalesTable, false, _creditMaxCheck);

    //orig: salestable: WHSInventTransSumDimEnumerator inventTransSumDimEnumerator = WhsWarehouseRelease::buildReleaseQuery(_salesTable.SalesId).forNotWMSOrder(WMSOrderStatus::New, WMSOrderStatus::InExpedition).getEnumerator();
    //@analogous to WHSTmpReleaseToWarehouse::createFromSalesLine()
    WHSInventTransSumDimEnumerator inventTransSumDimEnumerator = new WHSInventTransSumDimQuery().forInventTransId(_salesLine.InventTransId)
                                                                .forNotWMSOrder(WMSOrderStatus::New, WMSOrderStatus::InExpedition).getEnumerator();

    boolean lineReleased = WhsWarehouseRelease::createTmpReleaseToWarehouseLines(inventTransSumDimEnumerator, releaseToWarehouse, releaseToWarehouseId, WHSModule::Sales);

    if (lineReleased)
    {
        //not: using (WHSInstrumentationReleaseToWarehousePerformanceTask perfTask = WHSInstrumentationReleaseToWarehousePerformanceTask::newFromReleaseToWarehouseId(releaseToWarehouseId, 'releaseSingleSalesOrder'))
        {
            WHSWarehouseRelease::releaseToWarehouse(releaseToWarehouse, releaseToWarehouseId, false, true);
        }
    }

}

/// <summary>
/// Check delivery address settings for sales order
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
protected static void checkSalesOrderDeliveryName_AVA(SalesTable _salesTable)
{   //@analogous to checkSalesOrderDeliveryName
    if (WhsWarehouseRelease::useSalesLineDeliveryAddress())
    {
        if (SalesLine::existBySalesIdAndDeliveryName(_salesTable.SalesId, ''))
        {
            throw error(strFmt("@WAX:ReleaseToWarehouseError_SalesOrderMissingDeliveryName", _salesTable.SalesId));
        }
    }
    else if (!_salesTable.DeliveryName)
    {
        throw error(strFmt("@WAX:ReleaseToWarehouseError_SalesOrderMissingDeliveryName", _salesTable.SalesId));
    }
}
